import {initialState,chooseMode,chooseTopic,changePolicy,solveMath,nextMath,mathQuestions,record} from './demo-model.mjs';
const content=document.querySelector('#watch-content');
const status=document.querySelector('#demo-status');
const icon=(name)=>`<svg aria-hidden="true" focusable="false"><use href="/assets/icons.svg#${name}"></use></svg>`;
const esc=(text)=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=initialState(),data,story,playing=false;
const player=new Audio();player.preload='none';
const labels={moon:'Moon',seed:'Seeds',butterfly:'Butterflies'};
const observations={moon:'With a grown-up, notice the Moon on a few evenings. Does the bright part look the same?',seed:'With a grown-up, look at a seed and a plant. What do you notice?',butterfly:'If you spot a butterfly with a grown-up, watch where it lands. Give it plenty of space.'};
function announce(text){if(status)status.textContent=text;}
function stopAudio(){player.pause();player.removeAttribute('src');player.load();playing=false;updateAudioButton();}
function updateAudioButton(){const b=document.querySelector('[data-action="listen"]');if(b){b.innerHTML=icon(playing?'pause':'play')+`<span>${playing?'Pause':'Listen'}</span>`;b.setAttribute('aria-label',playing?'Pause narration':'Play recorded Trustin narration');}const f=document.querySelector('#audio-note');if(f)f.textContent=playing?'Recorded Trustin voice · You can read or move on anytime':'Read at your pace · Sound starts only when you press Listen';}
function audioSource(){if(state.view==='discovery'){const t=data.find(x=>x.illustration===state.topic);return `/assets/audio/${t.id}.v${t.version}-${state.page===0?'answer':'more'}.m4a`;}if(state.view==='story')return `/assets/story/${story.nodes[state.storyPage].audio}`;return null;}
async function toggleAudio(){const src=audioSource();if(!src)return;if(playing){player.pause();return;}if(player.getAttribute('src')!==src)player.src=src;if(player.ended)player.currentTime=0;player.playbackRate=state.pace;try{await player.play();}catch{announce('Audio could not play here. The complete text is available in the watch.');playing=false;updateAudioButton();}}
player.addEventListener('play',()=>{playing=true;updateAudioButton();});player.addEventListener('pause',()=>{playing=false;updateAudioButton();});player.addEventListener('ended',()=>{playing=false;updateAudioButton();});player.addEventListener('error',()=>{if(player.getAttribute('src'))announce('The recording could not load. You can keep reading the text.');playing=false;updateAudioButton();});
function topicButton(t){return `<button class="topic-button" data-topic="${t}" aria-label="Explore the ${labels[t]} sample">${icon(t)}<span>${labels[t]}</span></button>`;}
function controls(back=true,next='Next'){return `<div class="reader-controls"><button data-action="back" aria-label="Previous page" ${back?'':'disabled'}>${icon('back')}<span>Back</span></button><button data-action="listen" aria-label="Play recorded Trustin narration">${icon('play')}<span>Listen</span></button><button data-action="next">${icon('next')}<span>${next}</span></button></div><p class="reader-foot" id="audio-note">Read at your pace · Sound starts only when you press Listen</p>`;}
function renderDock(){const log=document.querySelector('#activity-log');log.innerHTML=state.log.length?`<ul>${state.log.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p>Finish a discovery, story or math sample. Your demo activity will appear here.</p>';document.querySelector('#topic-policy').value=state.moonPolicy;document.querySelector('#narration-pace').value=String(state.pace);document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===state.mode)));}
function render(){if(!data||!story)return;let html='';
if(state.view==='home')html=`<p class="demo-kicker">Ask Trustin</p><img class="demo-avatar" src="/assets/trustin.png" alt="Trustin, a small teal learning character" width="297" height="349"><div class="topic-shelf">${topicButton('seed')}${topicButton('moon')}${topicButton('butterfly')}</div><button class="mic-button" data-action="questions" aria-label="Choose a sample question; no microphone recording">${icon('mic')}</button><p class="demo-hint">Tap a topic, or choose a sample question.</p>`;
if(state.view==='questions')html=`<p class="demo-kicker">A little question</p><h3 class="watch-title">What do you wonder?</h3><div class="question-choices">${['moon','seed','butterfly'].map(t=>`<button class="question-choice" data-topic="${t}">${esc(data.find(x=>x.illustration===t).question)}</button>`).join('')}</div><p class="demo-hint">Prepared examples · No microphone recording</p><button class="reset" data-action="home">Back to Ask Trustin</button>`;
if(state.view==='discovery'){const t=data.find(x=>x.illustration===state.topic);html=`<p class="demo-kicker">${esc(labels[state.topic])}</p><h3 class="watch-title">${esc(t.question)}</h3><div class="reader-art topic-art">${icon(state.topic)}</div><div class="reader-text" tabindex="0" aria-label="Sample answer">${esc(state.page===0?t.explanation:t.continuation)}</div><p class="reader-progress">${state.page+1} of 2 · A prepared discovery</p>${controls(true,state.page===1?'Finish':'Next')}`;}
if(state.view==='boundary')html=`<p class="demo-kicker">A question for together</p><div class="done-icon">${icon('parents')}</div><h3 class="watch-title">Let’s ask your grown-up.</h3><p class="ending">Your grown-up has chosen to explore Moon questions together.<small>Try a different topic, or change the Moon setting in the sample Parent Dock.</small></p><button class="button watch-cta" data-action="home">Explore something else</button>`;
if(state.view==='story'){const n=story.nodes[state.storyPage];html=`<p class="demo-kicker">Storytime</p>${state.storyPage===0?'<h3 class="watch-title">Trustin and the<br>Curled Leaf</h3>':''}<img class="reader-art" src="/assets/story/${n.art}.jpg" alt="${n.art==='repot'?'Trustin helps a gardener move the plant to a new pot':n.art==='later'?'Trustin returns to the plant as a new leaf opens':'Trustin notices a curled leaf beside a watering can'}" width="480" height="320"><div class="reader-text" tabindex="0" aria-label="Story text">${esc(n.text)}</div><p class="reader-progress">${state.storyPage===0?'Story introduction':`Page ${state.storyPage} of ${story.nodes.length-1}`}</p>${controls(state.storyPage>0,state.storyPage===story.nodes.length-1?'Finish':'Next')}`;}
if(state.view==='mathIntro')html=`<p class="demo-kicker">Little garden math</p><div class="reader-art topic-art">${icon('math')}</div><h3 class="watch-title">A few seeds.<br>A little counting.</h3><p class="ending">Help get the garden ready.<br>Three small counting challenges.<small>This browser sample uses text and pictures.</small></p><button class="button watch-cta" data-action="startMath">Let’s try</button>`;
if(state.view==='math'){const q=mathQuestions[state.mathPage];html=`<p class="demo-kicker">Little garden math · ${state.mathPage+1} / 3</p><h3 class="watch-title">${esc(q.prompt)}</h3><div class="math-display" aria-label="${q.count} seeds">${Array.from({length:q.count},()=>icon('seedling')).join('')}</div><div class="math-options">${q.options.map(n=>`<button data-number="${n}" aria-label="${n} seeds" ${state.mathSolved?'disabled':''} class="${state.mathSolved&&n===q.answer?'correct':''}">${n}</button>`).join('')}</div><p class="math-message" role="status">${esc(state.mathFeedback||'Take your time. Count the seeds if it helps.')}</p>${state.mathSolved?'<button class="button watch-cta" data-action="nextMath">'+(state.mathPage===2?'Finish':'Next little challenge')+'</button>':''}`;}
if(state.view==='done'){const text=state.mode==='ask'?observations[state.topic]:state.mode==='story'?'Trustin learned to look, check, and ask. What could you notice together today?':'You helped with the garden. With a grown-up, try counting four things around you.';html=`<p class="demo-kicker">A little discovery, complete</p><div class="done-icon">${icon('spark')}</div><h3 class="watch-title">${state.mode==='story'?'The end.':'Now, take it into the world.'}</h3><p class="ending">${esc(text)}<small>A natural place to pause. No next activity starts automatically.</small></p><button class="button watch-cta" data-action="home">Back to the demo home</button>`;}
content.innerHTML=html;renderDock();updateAudioButton();}
function focusContent(){content.setAttribute('tabindex','-1');content.focus({preventScroll:true});}
content?.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.action==='listen'){toggleAudio();return;}if(b.dataset.number!==undefined){solveMath(state,b.dataset.number);render();return;}stopAudio();if(b.dataset.topic){chooseTopic(state,b.dataset.topic);announce(state.view==='boundary'?'Your sample topic boundary is active.':'Prepared discovery opened.');}else{switch(b.dataset.action){case'home':chooseMode(state,'ask');break;case'questions':state.view='questions';break;case'startMath':state.view='math';break;case'nextMath':nextMath(state);break;case'back':if(state.view==='story'){state.storyPage=Math.max(0,state.storyPage-1);}else if(state.page>0)state.page--;else state.view='home';break;case'next':if(state.view==='story'){if(state.storyPage<story.nodes.length-1)state.storyPage++;else{state.view='done';record(state,'Finished Trustin and the Curled Leaf');}}else if(state.page===0)state.page++;else{state.view='done';record(state,`Explored ${labels[state.topic].toLowerCase()}`);}break;}}render();focusContent();});
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{if(!data)return;stopAudio();chooseMode(state,b.dataset.mode);announce(`${b.textContent.trim()} sample opened.`);render();}));
document.querySelector('#topic-policy')?.addEventListener('change',e=>{if(!data)return;stopAudio();changePolicy(state,e.target.value);announce(state.moonPolicy==='together'?'Moon questions now go to a grown-up in this demo.':'Moon questions are now available in this demo.');render();});
document.querySelector('#narration-pace')?.addEventListener('change',e=>{state.pace=Number(e.target.value);player.playbackRate=state.pace;announce(`Narration pace changed to ${e.target.selectedOptions[0].textContent}.`);});
document.querySelector('#reset-demo')?.addEventListener('click',()=>{stopAudio();state=initialState();announce('Demo reset. Sample activity and settings cleared.');render();});
document.addEventListener('visibilitychange',()=>{if(document.hidden)player.pause();});
window.addEventListener('pagehide',()=>player.pause());
if(content){Promise.all([fetch('/assets/discoveries.json').then(r=>{if(!r.ok)throw Error();return r.json();}),fetch('/assets/story/book.json').then(r=>{if(!r.ok)throw Error();return r.json();})]).then(([d,s])=>{data=d;story=s;render();document.querySelectorAll('[data-mode],#topic-policy,#narration-pace,#reset-demo').forEach(b=>b.disabled=false);}).catch(()=>{content.innerHTML='<p class="ending">The sample could not load. Please reload the page to try again.</p>';announce('Demo unavailable. The philosophy and product pages are still available.');});}
document.querySelectorAll('[data-print]').forEach(b=>b.addEventListener('click',()=>window.print()));
document.querySelectorAll('[data-copy-email]').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText('hello@trustinjr.com');b.textContent='Email address copied';}catch{b.textContent='hello@trustinjr.com';}}));
